// caja de 7 marchas con desarrollos de F1 (velocidad punta de cada marcha, km/h) y corte a 18.500 rpm
const GEAR_KMH=[100,145,185,220,255,290,322],GV=GEAR_KMH.map(k=>k/KMH),GTOP=GEAR_KMH.length-1; // 6 marchas largas: cada una barre más vueltas
function gearHyst(v){let g=AU.gh==null?0:Math.min(AU.gh,GTOP);v=Math.max(0,v);while(g<GTOP&&v>GV[g]*0.99)g++;while(g>0&&v<GV[g-1]*0.87)g--;AU.gh=g;return g;}
function gearFor(v){let g=0;while(g<GTOP&&v>GV[g]*0.99)g++;return g;}
function engOf(v,g,thr){const e=18500*Math.max(0,v)/GV[g];return g===0?Math.max(e,thr>0.1?7500:4500):Math.max(e,4500);} // en 1.ª el embrague patina
function audioUpdate(){
  if(!AU.ctx)return;
  if(settings.engMode==='sample'&&!AU.smpSrc&&!AU.smpLoading){AU.smpLoading=true;engSampleStart();setTimeout(()=>AU.smpLoading=false,1500);}else if(settings.engMode!=='sample'&&AU.smpSrc)engSampleStop();
  const t=AU.ctx.currentTime,p=R&&!attract?R.player:null;
  if(AU.rn)AU.rn.gain.setTargetAtTime(R&&!paused&&!muted&&R.weather&&R.weather.type!=='dry'?Math.min(0.12,rainAt(R.weather,cam.x,cam.y)*0.13):0,t,0.3);
  if(!p||paused||muted||ui.resultsShown){AU.eg.gain.setTargetAtTime(0,t,0.05);if(AU.smpG)AU.smpG.gain.setTargetAtTime(0,t,0.05);if(AU.smpG2)AU.smpG2.gain.setTargetAtTime(0,t,0.05);if(AU.rgn)AU.rgn.gain.setTargetAtTime(0,t,0.05);if(AU.cg)AU.cg.gain.setTargetAtTime(0,t,0.1);if(AU.hg)AU.hg.gain.setTargetAtTime(0,t,0.1);if(AU.rv)AU.rv.forEach(V=>V.g.gain.setTargetAtTime(0,t,0.05));AU.sg.gain.setTargetAtTime(0,t,0.05);AU.rg.gain.setTargetAtTime(0,t,0.05);AU.gg.gain.setTargetAtTime(0,t,0.05);return;}
  const vf=p.vx*Math.cos(p.a)+p.vy*Math.sin(p.a);
  let target;
  if(R.phase==='countdown')target=p.lrpm||4500;
  else{const gi=gearHyst(vf);target=engOf(vf,gi,p.throttle);
    if(AU.lastGear!=null&&gi<AU.lastGear){AU.blip=0.17;if(Math.abs(vf)>150)audioPops(1+Math.floor(Math.random()*2));}if(AU.lastGear!=null&&gi>AU.lastGear)AU.snap=true;AU.lastGear=gi;}
  if(p.pit==='service')target=4500;
  const dtA=Math.min(0.05,t-(AU.lt||t));AU.lt=t;
  AU.blip=Math.max(0,(AU.blip||0)-dtA);
  if(AU.blip>0)target+=2600; // golpe de gas al reducir: más agresivo
  // v44: si las ruedas patinan, el motor se dispara de vueltas (sin ayudas); con ayudas, el control de tracción las corta a tirones
  const spw=p.spinW||0;if(spw>0.05&&R.phase==='race')target=Math.min(18500,target+(R.aids?900:5200)*spw);
  if(AU.rpm==null||AU.rpm<100)AU.rpm=target;
  AU.rpm+=(target-AU.rpm)*Math.min(1,(target>AU.rpm?(AU.blip>0?14:4.6):6.5)*dtA);   // inercia del motor: subidas y bajadas de vueltas más rápidas y bruscas
  if(AU.snap){AU.rpm=target;AU.snap=false;}
  const eng=AU.rpm;
  const thr=Math.max(p.throttle,AU.blip>0?0.9:0);
  engineSet(AU,eng,thr,t);
  // corte de encendido al subir de marcha
  const gi2=AU.lastGear||0;if(AU.upG!=null&&gi2>AU.upG){AU.cut=0.05;}AU.upG=gi2;AU.cut=Math.max(0,(AU.cut||0)-dtA);
  if(R.aids&&spw>0.06&&((t*22)%1)<0.35)AU.cut=Math.max(AU.cut,0.02); // tartamudeo del control de tracción
  const useS=!!AU.smpSrc&&settings.engMode==='sample',vol=p.pit==='service'?0.05:AU.cut>0?0.03:0.1+0.26*thr+(AU.blip>0?0.06:0);
  AU.eg.gain.setTargetAtTime(useS?0:vol,t,AU.cut>0?0.006:0.04);
  if(useS){AU.smpSrc.playbackRate.setTargetAtTime(clamp(eng/engSampleRef(),0.2,1.6),t,0.02);AU.smpG.gain.setTargetAtTime(vol*1.6,t,AU.cut>0?0.006:0.04);}
  // petardeos al soltar el gas a altas vueltas
  if(AU.prevThr>0.5&&p.throttle<0.1&&eng>13000&&Math.abs(vf)>120)audioPops(3+Math.floor(Math.random()*4));
  AU.prevThr=p.throttle;
  // motor de rivales cercanos
  {let best=null,bd=1e9;for(const c of R.cars){if(c===p||c.dnf||c.pit==='service')continue;const d=Math.hypot(c.x-p.x,c.y-p.y);if(d<bd){bd=d;best=c;}}
   if(best&&bd<420){const dx=best.x-p.x,dy=best.y-p.y,rv=((best.vx-p.vx)*dx+(best.vy-p.vy)*dy)/Math.max(1,bd),dop=clamp(1-rv/1150,0.75,1.3);
     const bv=Math.hypot(best.vx,best.vy),F2=engOf(bv,gearFor(bv),best.throttle)/160*dop*engPitchF();
     const rg=0.055*Math.pow(1-bd/420,1.6)*(0.4+0.6*best.throttle);
     if(AU.smpSrc2&&settings.engMode==='sample'){AU.smpSrc2.playbackRate.setTargetAtTime(clamp(F2*160/engPitchF()/engSampleRef(),0.2,1.7),t,0.04);AU.smpG2.gain.setTargetAtTime(rg*1.5,t,0.06);AU.rgn.gain.setTargetAtTime(0,t,0.06);}
     else{AU.r1.frequency.setTargetAtTime(F2,t,0.04);AU.rgn.gain.setTargetAtTime(rg,t,0.06);}
     if(AU.rpan){const ang=Math.atan2(dy,dx)+(camMode==='rot'?cam.rot:0);AU.rpan.pan.setTargetAtTime(clamp(Math.cos(ang),-0.9,0.9),t,0.05);}
     // v44: soplido de aire cuando un coche pasa pegado a mucha más (o menos) velocidad
     const rel=Math.hypot(best.vx-p.vx,best.vy-p.vy);if(bd<55&&rel>70&&t-(best._whoosh||0)>1.2){best._whoosh=t;audioWhoosh(Math.min(1,rel/260),AU.rpan?clamp(Math.cos(Math.atan2(dy,dx)+(camMode==='rot'?cam.rot:0)),-0.9,0.9):0);}}
   else{AU.rgn.gain.setTargetAtTime(0,t,0.1);if(AU.smpG2)AU.smpG2.gain.setTargetAtTime(0,t,0.1);}}
  AU.sg.gain.setTargetAtTime(paved(p.surf)?Math.min(0.22,(p.skidV!=null?p.skidV:p.skid)*0.32):0,t,0.03);
  AU.rg.gain.setTargetAtTime(!paved(p.surf)&&Math.abs(vf)>30?0.35:p.surf==='kerb'&&Math.abs(vf)>60?0.22:0,t,0.05);
  // pistolas neumáticas durante la parada
  // pistolas neumáticas: la tuya y las de los boxes cercanos (cada coche con su ritmo)
  let gv=p.pit==='service'&&p.pitTotal-p.pitT<2.4&&((t*7)%1)<0.5?0.18:0;
  for(const c of R.cars){if(c===p||c.pit!=='service'||c.pitTotal-c.pitT>2.4)continue;const d=Math.hypot(c.x-cam.x,c.y-cam.y);if(d>900)continue;if(((t*6.3+c.slot*0.37)%1)<0.45)gv=Math.max(gv,0.12*(1-d/900));}
  AU.gg.gain.setTargetAtTime(gv,t,0.01);
  // otros dos rivales cercanos (además del más próximo), más lejos y más suaves
  if(AU.rv){const near=R.cars.filter(c=>c!==p&&!c.dnf&&c.pit!=='service').map(c=>({c,d:Math.hypot(c.x-p.x,c.y-p.y)})).sort((a,b)=>a.d-b.d).slice(1,3);
    AU.rv.forEach((V,i)=>{const n=near[i];if(n&&n.d<900){const bv=Math.hypot(n.c.vx,n.c.vy);V.o.frequency.setTargetAtTime(engOf(bv,gearFor(bv),n.c.throttle)/160*engPitchF(),t,0.05);V.g.gain.setTargetAtTime(0.03*Math.pow(1-n.d/900,1.8)*(0.4+0.6*n.c.throttle),t,0.08);
      if(V.pn){const ang=Math.atan2(n.c.y-p.y,n.c.x-p.x)+(camMode==='rot'?cam.rot:0);V.pn.pan.setTargetAtTime(clamp(Math.cos(ang),-0.9,0.9),t,0.08);}}else V.g.gain.setTargetAtTime(0,t,0.1);});}
  // público: más fuerte cerca de la recta de meta y en salidas, adelantamientos del jugador y final
  if(AU.cg){const tr=R.tr,ds=Math.hypot(cam.x-tr.xs[0],cam.y-tr.ys[0]),base=0.012+0.03*Math.max(0,1-ds/2500);
    const pos=R.standings?R.standings.indexOf(p):0;if(ui.lastPosA!=null&&pos<ui.lastPosA)ui.cheer=1.5;ui.lastPosA=pos;if(R.phase==='countdown'||p.finished)ui.cheer=Math.max(ui.cheer||0,0.6);
    ui.cheer=Math.max(0,(ui.cheer||0)-dtA*0.6);AU.cg.gain.setTargetAtTime(base*(1+0.25*Math.sin(t*0.7))+0.05*ui.cheer,t,0.3);
    AU.hg.gain.setTargetAtTime(R.phase==='race'?0.01:0,t,0.5);AU.hum.frequency.setTargetAtTime(90+20*Math.sin(t*0.3),t,0.5);}
}

