// Neumático Litostone (marca inventada) visto de lado, con la banda del color de cada compuesto
function tyreSvg(k,s){const C=COMPOUNDS[k],id='ty'+k+s,lab={S:'SOFT',M:'MEDIUM',H:'HARD',I:'INTER',W:'WET'}[k];
  let tread='';for(let i=0;i<36;i++){const a=i*Math.PI/18;tread+=`<rect x="48.6" y="1.2" width="2.8" height="5" rx="1" fill="#000" opacity=".55" transform="rotate(${a*57.3} 50 50)"/>`;}
  let sp='';for(let i=0;i<10;i++)sp+=`<path d="M50 50 L47.6 28 Q50 26.5 52.4 28 Z" fill="url(#${id}m)" stroke="#5d6672" stroke-width=".4" transform="rotate(${i*36} 50 50)"/>`;
  return `<svg class="tyre" width="${s}" height="${s}" viewBox="0 0 100 100" aria-label="Neumático ${C.name}"><defs>
   <radialGradient id="${id}r" cx=".4" cy=".35" r=".75"><stop offset="0" stop-color="#3b3d42"/><stop offset=".72" stop-color="#17181b"/><stop offset="1" stop-color="#060607"/></radialGradient>
   <linearGradient id="${id}m" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4f7fa"/><stop offset=".55" stop-color="#8d97a3"/><stop offset="1" stop-color="#cfd6de"/></linearGradient>
   <path id="${id}t" d="M14 50 A36 36 0 0 1 86 50"/><path id="${id}b" d="M8.6 50 A41.4 41.4 0 0 0 91.4 50"/></defs>
   <circle cx="50" cy="50" r="49" fill="url(#${id}r)"/>${tread}
   <circle cx="50" cy="50" r="44.5" fill="none" stroke="#000" stroke-opacity=".5" stroke-width="1"/>
   <circle cx="50" cy="50" r="33.5" fill="none" stroke="${C.color}" stroke-width="3.4"/>
   <text font-family="Arial Black,Arial,sans-serif" font-weight="900" font-size="8.6" letter-spacing="1.6" fill="#f2f2f2"><textPath href="#${id}t" startOffset="50%" text-anchor="middle">LITOSTONE</textPath></text>
   <text font-family="Arial,sans-serif" font-weight="800" font-size="6.6" letter-spacing="1.4" fill="${C.color}"><textPath href="#${id}b" startOffset="50%" text-anchor="middle">${lab}</textPath></text>
   <circle cx="50" cy="50" r="27" fill="#2a2e35"/>${sp}<circle cx="50" cy="50" r="27" fill="none" stroke="url(#${id}m)" stroke-width="2"/>
   <circle cx="50" cy="50" r="6.5" fill="#1b1d21" stroke="${C.color}" stroke-width="2"/><ellipse cx="38" cy="26" rx="16" ry="7" fill="#fff" opacity=".07" transform="rotate(-25 38 26)"/></svg>`;}
// iconos sencillos dibujados (sin imágenes externas)
