const SETUP_KEYS=[['wing','Alerón','Más agarre en curva rápida, menos punta'],['brake','Frenos','Más potencia, pero bloqueas antes'],['gear','Cambio','Bajo: acelera más; alto: más punta'],['tc','Control de tracción','Bajo: sale mejor pero se va la trasera']];
function setupRec(ti){return {wing:Math.round(TRACKS[ti].wing*9+1),brake:5,gear:Math.round(TRACKS[ti].gear*9+1),tc:6};}
function setupOf(ti){settings.setups2=settings.setups2||{};const r=setupRec(ti),s0=settings.setups2[ti]||{};return Object.assign({},r,s0);}
function setupNorm(ti){const s0=setupOf(ti);return {wing:(s0.wing-1)/9,brake:(s0.brake-1)/9,gear:(s0.gear-1)/9,tc:(s0.tc-1)/9};}
function wingVal(ti){return setupOf(ti).wing;}
function wingHtml(ti){const v=setupOf(ti),r=setupRec(ti);
  return `<div class="steerAdj"><span class="fl" style="margin-top:12px">Reglaje · ${esc(TRACKS[ti].short||TRACKS[ti].name)}</span>`+SETUP_KEYS.map(([k,l,h])=>
   `<div class="sl" title="${h}"><span>${l} <span style="opacity:.5">(rec. ${r[k]})</span></span><input type="range" min="1" max="10" step="1" value="${v[k]}" data-setup="${k}" data-ti="${ti}"><span class="v">${v[k]}</span></div>`).join('')+
   `<div class="setupFx" id="setupFx_${ti}">${setupFxHtml(ti)}</div><div class="hint">${SETUP_KEYS.map(x=>x[1]+': '+x[2].toLowerCase()).join(' · ')}.</div></div>`;}
// efecto del reglaje, calculado con la misma física del coche, comparado con el recomendado para este circuito
function setupFx(st){const w=(st.wing-1)/9,g=(st.gear-1)/9,b=(st.brake-1)/9,tc=(st.tc-1)/9;
  const cd=CD*(0.88+0.24*w);let v=VMAX;for(let i=0;i<40;i++){v=Math.cbrt(Math.max(1,PWR-ROLL*v)/cd);} v=Math.min(v,VMAX*(0.93+0.12*g)*1.05);
  return {top:v*KMH,fast:wingAero({wing:w},VMAX),acc:(1.12-0.24*g),brk:(0.85+0.3*b),lock:(0.8+0.4*b),trac:tc};}
function setupFxHtml(ti){const a=setupFx(setupOf(ti)),r=setupFx(setupRec(ti));
  const pc=(x,y,inv)=>{const d=Math.round((x/y-1)*100);if(!d)return '<span style="opacity:.6">=</span>';const good=inv?d<0:d>0;return `<b style="color:${good?'#3ddc84':'#ff8a65'}">${d>0?'+':''}${d}%</b>`;};
  const dTop=Math.round(a.top-r.top);
  // barra: 50 % = recomendado; cada 10 % de diferencia mueve la barra un cuarto
  const bar=(x,y,txt)=>{const d=(x/y-1),f=clamp(0.5+d*2.5,0.04,1);const col=Math.abs(d)<0.005?'#5aa0ff':d>0?'#3ddc84':'#ff8a65';
    return `<div class="fxbar"><i style="width:${(f*100).toFixed(0)}%;background:linear-gradient(90deg,${col}55,${col})"></i><b class="mid"></b></div><span class="fxv">${txt}</span>`;};
  return `<div class="fxgrid">
   <span>Velocidad punta</span>${bar(a.top,r.top,Math.round(a.top)+' km/h'+(dTop?` <b style="color:${dTop>0?'#3ddc84':'#ff8a65'}">(${dTop>0?'+':''}${dTop})</b>`:''))}
   <span>Agarre en curva rápida</span>${bar(a.fast,r.fast,pc(a.fast,r.fast))}
   <span>Aceleración en salida</span>${bar(a.acc,r.acc,pc(a.acc,r.acc))}
   <span>Potencia de frenada</span>${bar(a.brk,r.brk,pc(a.brk,r.brk)+(a.lock>r.lock+0.01?' <small style="opacity:.7">bloquea antes</small>':''))}</div>
   <div class="hint" style="margin-top:2px">Comparado con el reglaje recomendado para este circuito.</div>`;}
