function restartSession(){if(!EV)return;if(R.practice)startPractice();else if(R.mode==='quali')startQuali();else startRace(true);}
$('resume').onclick=()=>setPaused(false);
$('restart1').onclick=restartSession;$('replay1').onclick=()=>{showOnly(null);paused=false;startReplay();};$('endq').onclick=()=>{if(R&&R.liveQ){const p=R.player;if(!p.pit){p.pit='service';p.pitT=1e9;p.vx=p.vy=0;p.qFly=false;}p.qDone=true;ui.qSkip=true;ui.qFast=0;flash('Terminas tu sesión','Se simula el resto: los rivales completan sus vueltas',2.5);showOnly(null);paused=false;return;}if(R.practice&&EV.weekend){EV.stage='quali';showOnly(null);paused=false;goQualiOrRace();}else endQuali();};$('tomenu1').onclick=leaveToMenu;
// v45: pantalla completa. En Android/PC se pide al navegador (y se gira a horizontal); en iPhone Safari no lo permite en páginas web:
// se explica cómo añadir el juego a la pantalla de inicio, que lo abre sin barras. Abierto desde ese icono, el botón no hace falta.
const IS_IOS=/iP(hone|od|ad)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const IS_APP=window.matchMedia&&(matchMedia('(display-mode: fullscreen)').matches||matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true;
function fullHelp(){
  const ios=IS_IOS,box=document.createElement('div');box.className='overlay';box.id='fullHelp';
  box.innerHTML=`<div class="card"><h2>Pantalla completa</h2><p class="sub">${ios?'En iPhone, Safari no deja poner una página web a pantalla completa. Pero puedes instalar el juego como app:':'Tu navegador no ha dejado activarla. Prueba a instalar el juego como app:'}</p>
    <ol style="line-height:1.7;font-size:15px;padding-left:20px">${ios?'<li>Abre el juego en <b>Safari</b>.</li><li>Pulsa el botón <b>Compartir</b> (el cuadrado con la flecha hacia arriba).</li><li>Elige <b>Añadir a pantalla de inicio</b> y pulsa <b>Añadir</b>.</li><li>Abre Mini GP desde el icono nuevo: se verá a pantalla completa.</li>':'<li>Abre el menú del navegador (⋮ arriba a la derecha).</li><li>Pulsa <b>Instalar aplicación</b> o <b>Añadir a pantalla de inicio</b>.</li><li>Abre Mini GP desde el icono nuevo.</li>'}</ol>
    <button class="go" id="fullHelpOk">Entendido</button></div>`;
  document.body.appendChild(box);$('fullHelpOk').onclick=()=>box.remove();}
async function goFull(){
  const el=document.documentElement,rq=el.requestFullscreen||el.webkitRequestFullscreen;
  if(document.fullscreenElement||document.webkitFullscreenElement){(document.exitFullscreen||document.webkitExitFullscreen).call(document);return;}
  if(!rq){fullHelp();return;}
  try{await rq.call(el,{navigationUI:'hide'});try{if(screen.orientation&&screen.orientation.lock&&matchMedia('(pointer: coarse)').matches)await screen.orientation.lock('landscape');}catch(e){}}
  catch(e){fullHelp();}
}
