      if(c.dWing>0.25&&c.dWing<=0.6&&Math.random()<0.35)spawn(c.x+fx2*18,c.y+fy2*18,c.vx*0.5+(Math.random()-0.5)*60,c.vy*0.5+(Math.random()-0.5)*60,0.2+Math.random()*0.2,1,'spark');
      // v44: sin rueda, el buje va arrastrando por el asfalto: chispas continuas y algo de humo
