// ---------- estrategia en la pausa: ¿qué pasa si paro ahora? ----------
function pitLossEst(){const tr=R.tr,len=(2*PITL+2*PITE-10)*tr.sp,avg=Math.max(250,tr.len/Math.max(30,(R.player.lastLap||R.est.lap||100)));
  const p=R.player,fpl=fplOf(R,p),fuelAdd=clamp(lapsLeft(R,p)*fpl*1.08+2-p.fuel,0,TANK-p.fuel);
  return {loss:len/PIT_V-len/avg+2.2+2.4+fuelAdd*0.06+2,fuelAdd};}
function strategyHtml(){
  if(!R||R.mode!=='race'||R.phase!=='race')return '';const p=R.player;if(p.finished||p.dnf)return '';
  const st=R.standings,pos=st.indexOf(p),{loss,fuelAdd}=pitLossEst(),v=Math.max(200,Math.hypot(p.vx,p.vy)||300),lap=p.lastLap||R.est.lap||100,spd=R.tr.len/lap;
  // posición al salir: los que vienen detrás a menos de 'loss' segundos me pasan
  let after=pos;const passed=[];for(let k=pos+1;k<st.length;k++){const o=st[k];if(o.dnf||o.finished)continue;const gap=(p.prog-o.prog)*R.tr.sp/spd;if(gap<loss){after++;passed.push(o.name+' (+'+gap.toFixed(1)+' s)');}}
  const ahead=st[after]&&st[after]!==p?st[after]:null;
  const left=lapsLeft(R,p),C=k=>COMPOUNDS[k],life=k=>{const w=(R.est.wear||0.05)*C(k).wear;return Math.floor(0.85/Math.max(0.001,w));};
  const wn=typeof wetNeed==='function'?wetNeed(R,p):0,best=compoundFor(R,p,p.nextCompound||'M'),keys=wn>0.17?['W','I','M']:wn>0.07?['I','S','M','H']:['S','M','H'];
  const rows=keys.map(k=>`<tr><td>${tyIco(k)} ${C(k).name}${k===best?' <b style="color:#2ee66b">· recomendado</b>':''}</td><td class="r">~${life(k)} v</td><td class="r">${life(k)>=left?'<b style="color:#2ee66b">llega al final</b>':'otra parada'}</td>${R.sets?`<td class="r">${R.sets[k]} nuevos</td>`:''}</tr>`).join('');
  return `<div class="strat"><span class="fl">Estrategia · si paras ahora</span>
    <p class="sub" style="margin:2px 0 6px">Pierdes ~<b>${loss.toFixed(1)} s</b> (limitador ${(190*R.tr.sp/PIT_V).toFixed(1)} s + parada${fuelAdd>1?' con '+Math.round(fuelAdd)+' L':''}). Saldrías <b>P${after+1}</b> (ahora P${pos+1})${passed.length?', te pasarían '+passed.slice(0,3).join(', ')+(passed.length>3?'…':''):', sin perder posiciones'}.</p>
    <table><tr style="opacity:.6"><td>Neumático</td><td class="r">Duración</td><td class="r">Quedan ${left} v</td>${R.sets?'<td class="r">Juegos</td>':''}</tr>${rows}</table>
    <p class="sub" style="margin-top:6px">Tus gomas: ${COMPOUNDS[p.compound].name}, ${Math.round((1-p.wear)*100)}% · gasolina para ${(p.fuel/(fplOf(R,p))).toFixed(1)} vueltas.</p></div>`;
}
// ---------- ingeniero por radio ----------
const RADIO={q:[],cur:null,t:0,cool:{},last:0};
function radioSay(txt,key,cool,prio){
  if(!R||attract||!settings.radio)return;const now=R.t;
  if(key){if(RADIO.cool[key]!=null&&now<RADIO.cool[key])return;}
  // menos charla: los avisos no urgentes respetan un silencio mínimo entre mensajes (más largo en «Solo lo importante»)
  const quiet=(settings.radioLvl==null?0:settings.radioLvl)===0;
  if(!prio){if(now-RADIO.last<(quiet?28:12)||RADIO.q.length)return;}
  if(key)RADIO.cool[key]=now+(cool||30)*(quiet&&!prio?1.8:1);
  RADIO.last=now;
  if(prio)RADIO.q.unshift({txt,prio});else RADIO.q.push({txt,prio});if(RADIO.q.length>3)RADIO.q.length=3;
}
function radioUpdate(dt){
  const el=$('radio');if(!el)return;
  if(RADIO.cur){RADIO.t-=dt;if(RADIO.t<=0){RADIO.cur=null;el.classList.remove('on');}}
  if(!RADIO.cur&&RADIO.q.length&&!paused){const m=RADIO.q.shift();RADIO.cur=m.txt;RADIO.t=Math.max(2.8,RADIO.cur.length*0.075);
    el.innerHTML='<b>🎧 Ingeniero</b>'+esc(RADIO.cur);el.classList.add('on');radioBeep();
    // en «Solo lo importante» la voz solo suena en los mensajes urgentes; el resto aparece escrito
    const lvl=settings.radioLvl==null?0:settings.radioLvl;
    if(settings.voice&&(m.prio||lvl===1)&&window.speechSynthesis&&!muted){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(RADIO.cur.replace(/\bP(\d+)/g,'pe $1').replace(/\.\s/g,', '));u.lang='es-ES';u.rate=1.06;u.pitch=1;u.volume=0.95;
      const v=pickVoice();if(v)u.voice=v;u.onend=()=>radioBeep(true);setTimeout(()=>speechSynthesis.speak(u),220);}catch(e){}}}
}
// la voz más natural disponible en el dispositivo: primero la elegida en Ajustes, luego las «neurales/naturales/online» en español de España
function esVoices(){try{return speechSynthesis.getVoices().filter(v=>/^es/i.test(v.lang));}catch(e){return [];}}
function voiceScore(v){const n=v.name;return (/^es(-|_)ES/i.test(v.lang)?40:0)+(/natural|neural|online/i.test(n)?100:0)+(/google/i.test(n)?60:0)+(/premium|enhanced|mejorad/i.test(n)?80:0)+(/(Álvaro|Alvaro|Elvira|Jorge|Mónica|Monica|Pablo)/i.test(n)?10:0)-(/compact|eloquence|espeak/i.test(n)?80:0);}
function pickVoice(){const vs=esVoices();if(!vs.length)return null;const pick=settings.voiceName&&vs.find(v=>v.name===settings.voiceName);return pick||vs.slice().sort((a,b)=>voiceScore(b)-voiceScore(a))[0];}
function radioBeep(end){if(!AU.ctx||muted)return;try{const ac=AU.ctx,t=ac.currentTime;
  // chasquido de estática de radio (como al pulsar el botón del intercomunicador)
  if(AU.buf){const n=ac.createBufferSource();n.buffer=AU.buf;const bp=ac.createBiquadFilter();bp.type='bandpass';bp.frequency.value=end?1500:2100;bp.Q.value=0.9;const g=ac.createGain();
    g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(end?0.07:0.05,t+0.012);g.gain.exponentialRampToValueAtTime(0.0001,t+(end?0.16:0.11));n.connect(bp);bp.connect(g);g.connect(AU.master);n.start(t,Math.random()*0.5);n.stop(t+0.18);}
  if(!end){const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=1250;g.gain.setValueAtTime(0.0001,t+0.05);g.gain.exponentialRampToValueAtTime(0.035,t+0.06);g.gain.exponentialRampToValueAtTime(0.0001,t+0.13);o.connect(g);g.connect(AU.master);o.start(t+0.05);o.stop(t+0.14);}
}catch(e){}}
function gapTo(a,b){return Math.abs(a.prog-b.prog)*R.tr.sp/Math.max(150,Math.hypot(a.vx,a.vy));}
function radioThink(){ // se llama 2 veces por segundo durante la carrera
  const p=R.player;if(!p||p.bot||R.mode!=='race'||R.phase!=='race'||p.finished||p.dnf)return;
  const C=COMPOUNDS[p.compound],st=R.standings,pos=st.indexOf(p),fpl=fplOf(R,p),left=lapsLeft(R,p);
  if(p.tt<C.win[0]-8&&Math.hypot(p.vx,p.vy)>120&&p.lap>=1)radioSay('Ruedas frías, '+Math.round(p.tt)+' grados. Cuidado en las primeras curvas.','cold',90);
  if(p.tt>C.win[1]+8)radioSay('Neumáticos muy calientes. Cuida las traseras al salir de las curvas.','hot',45);
  if(p.temp>119&&p.temp<=127)radioSay(p.dirty>0.4?'Temperatura alta, '+Math.round(p.temp)+' grados. Sal del rebufo un momento o pon el motor en ahorro.':'Temperatura alta, '+Math.round(p.temp)+' grados. Pon el motor en ahorro.','temp',35);
  if(p.temp>127)radioSay('¡Motor muy caliente! Modo ahorro ya o lo rompemos.','temp2',12,true);
  if(p.eng<0.3&&p.eng>0)radioSay('El motor está muy gastado, '+Math.round(p.eng*100)+' por ciento. Cuídalo o no acabamos.','engw',60);
  if(p.issue==='oil'&&p.eng<0.5)radioSay('La presión sigue cayendo. Motor al '+Math.round(p.eng*100)+' por ciento.','oil2',30);
  if(p.wear>0.72&&!p.pitReq)radioSay('Las gomas están al límite. Cuando quieras, box.','wear',60);
  if(left>1&&p.fuel<left*fpl*0.97&&!p.pitReq)radioSay('No llegas con la gasolina. Tienes para '+(p.fuel/fpl).toFixed(1)+' vueltas, tendrás que parar.','fuel',75);
  // rivales con carácter: el ingeniero te cuenta cómo es el que tienes delante o detrás
  if(pos>0&&!R.sc){const a=st[pos-1],T=a.traits;if(T&&T.style&&!a.dnf&&!a.pit&&gapTo(a,p)<1.1){const tip={defensor:'Va a cerrar la puerta: amágale y ataca por el otro lado.',agresivo:'Si le pasas, te la va a devolver en la siguiente frenada.',cuidadoso:'Al final del stint tendrá mejores gomas que tú.',rompe:'Sus gomas caerán pronto. Paciencia.',metronomo:'No esperes que falle, tendrás que ganártelo.',irregular:'Mantén la presión, suele cometer errores.'}[T.style];
    radioSay(a.name+' '+STYLES[T.style].n+'. '+tip,'chr_'+a.id,600);}}
  if(pos<st.length-1&&!R.sc){const b=st[pos+1],T=b.traits;if(T&&T.style&&(T.style==='agresivo'||T.style==='irregular')&&!b.dnf&&!b.pit&&gapTo(p,b)<0.8)radioSay('Cuidado, detrás tienes a '+b.name+', '+STYLES[T.style].n+'.','chrB_'+b.id,600);}
  if(pos>0&&!R.sc){const a=st[pos-1];if(!a.dnf&&!a.pit){const g=gapTo(a,p);
    if(g<1.4&&a.wear>0.6)radioSay(a.name+' tiene las gomas muy gastadas. Apriétale.','prey_'+a.id,60);
    else if(g<0.9&&p.drsOk)radioSay('Tienes DRS. Ataca en la recta.','drs',40);}}
  /* v46: el ingeniero cuenta lo que hacen los rivales: paradas de los que tienes cerca, vueltas rápidas y abandonos */
  {const rv=ui.rv||(ui.rv={pit:{},fl:null,out:{}});
    for(let k=Math.max(0,pos-2);k<=Math.min(st.length-1,pos+2);k++){const o=st[k];if(o===p)continue;
      if(o.pit==='in'&&!rv.pit[o.id]){rv.pit[o.id]=true;radioSay(o.name+' entra en boxes'+(k<pos?', el que tienes delante.':'.')+(k===pos+1?' Aprieta ahora.':''),'rp_'+o.id+'_'+o.stops,20);}
      if(!o.pit&&rv.pit[o.id])rv.pit[o.id]=false;}
    let fl=null;for(const o of R.cars)if(o.bestLap&&(!fl||o.bestLap<fl.bestLap))fl=o;
    if(fl&&fl!==p&&p.lap>=3&&(!rv.fl||fl.bestLap<rv.fl-0.05)){rv.fl=fl.bestLap;radioSay('Vuelta rápida de '+fl.name+': '+fmt(fl.bestLap)+'.','fl',25);}else if(fl)rv.fl=Math.min(rv.fl||1e9,fl.bestLap);
    for(const o of R.cars)if(o.dnf&&!rv.out[o.id]&&o!==p){rv.out[o.id]=true;if(o.dnfReason!=='Accidente')radioSay(o.name+' abandona: '+(o.dnfReason||'avería').toLowerCase()+'.','out_'+o.id,0);}}
  if(R.weather&&R.weather.type!=='dry'&&R.t-(ui.radarT||-99)>8){ui.radarT=R.t;const fc=rainForecast(R);ui.radar=null;
    if(fc){const lap=(p.lastLap||R.est.lap||100),now=fc[0].f;
      if(now<0.12){const h=fc.find(x=>x.f>0.3);if(h){const sec=h.sec.indexOf(Math.max(...h.sec))+1,laps=h.h/lap;ui.radar='Lluvia en ~'+(laps<0.6?Math.round(h.h)+' s':laps.toFixed(1)+' v')+' · sector '+sec;
        radioSay('Radar: viene lluvia en '+(laps<0.6?'menos de un minuto':'unas '+laps.toFixed(1).replace('.',',')+' vueltas')+', sobre todo en el sector '+sec+'. Piensa en los intermedios.','radar',75);}}
      else if(now>0.35){const h=fc.find(x=>x.f<0.1);if(h){const laps=h.h/lap;ui.radar='Escampa en ~'+(laps<0.6?Math.round(h.h)+' s':laps.toFixed(1)+' v');radioSay('Radar: deja de llover en '+(laps<0.6?'menos de un minuto':'unas '+laps.toFixed(1).replace('.',',')+' vueltas')+'.','radar2',75);}}}}
  if(R.weather&&R.weather.type!=='dry'){const w=R.meanWet||0;if(w>0.18&&!C.wet)radioSay('La pista está mojada. Piensa en los intermedios.','rain',90);if(w<0.08&&C.wet&&R.weather.type!=='rain')radioSay('La pista se está secando. Los slicks ya funcionarían.','dry',90);}
}
function radioLap(p){ // al cruzar la meta
  const st=R.standings,pos=st.indexOf(p);if(p.lap===R.laps)radioSay('Última vuelta. ¡Vamos, a por todas!','last',999,true);
  if(p.lap>=2&&p.lap<=R.laps&&!R.sc){const a=st[pos-1],b=st[pos+1];let t='P'+(pos+1)+'.';
    if(a&&!a.dnf&&!a.finished)t+=' Delante, '+a.name+' a '+gapTo(a,p).toFixed(1)+'.';if(b&&!b.dnf)t+=' Detrás, '+b.name+' a '+gapTo(p,b).toFixed(1)+'.';radioSay(t,'gaps',5);}
}


// v45: el sol. Todas las sombras (coches, árboles, edificios) van hacia el mismo lado; al atardecer, más largas
function sunVec(){const t=settings.tod||'day';return t==='sunset'?{x:5.2,y:1.6,a:0.26}:t==='dusk'?{x:3.6,y:1.2,a:0.2}:t==='night'?{x:0.5,y:0.7,a:0.16}:{x:1.4,y:2.2,a:0.24};}
// ---------- hora del día: atardecer y noche con focos del circuito y faros ----------
let LIT=null;
function todDark(){const t=settings.tod||'day';if(t==='day')return 0;if(t==='sunset')return 0.22;if(t==='night')return 0.8;
  const lead=R.standings&&R.standings[0],pr=R.mode==='race'&&lead?clamp((lead.lap-1+lead.idx/R.tr.N)/Math.max(1,R.laps),0,1):0.5;return 0.12+0.6*pr;}
function drawLighting(cx,cy,rot,z,Rv){
  const dark=todDark();if(dark<=0.01)return;const tr=R.tr;
  if(!LIT||LIT.width!==cv.width||LIT.height!==cv.height){LIT=document.createElement('canvas');LIT.width=cv.width;LIT.height=cv.height;}
  const g=LIT.getContext('2d');g.setTransform(1,0,0,1,0,0);g.globalCompositeOperation='source-over';g.clearRect(0,0,LIT.width,LIT.height);
  const sunset=dark<0.4;g.fillStyle=sunset?`rgba(40,18,40,${dark*1.6})`:`rgba(4,8,26,${dark})`;g.fillRect(0,0,LIT.width,LIT.height);
  g.setTransform(DPR,0,0,DPR,0,0);g.translate(cx,cy);if(rot)g.rotate(cam.rot);g.scale(z,z);g.translate(-cam.x,-cam.y);
  g.globalCompositeOperation='destination-out';
  // focos a ambos lados de la pista
  const step=30;for(let i=0;i<tr.N;i+=step){const x=tr.xs[i],y=tr.ys[i];if(Math.abs(x-cam.x)>Rv+300||Math.abs(y-cam.y)>Rv+300)continue;
    for(const sg of [1,-1]){const lx=x+tr.nx[i]*sg*(W+40),ly=y+tr.ny[i]*sg*(W+40),gr=g.createRadialGradient(lx,ly,0,lx,ly,190);gr.addColorStop(0,'rgba(0,0,0,0.97)');gr.addColorStop(0.5,'rgba(0,0,0,0.6)');gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(lx-190,ly-190,380,380);}}
  // faros de los coches
  for(const c of R.cars){if(c.dnf&&!c.wrecked||c.gone)continue;if(Math.abs(c.x-cam.x)>Rv||Math.abs(c.y-cam.y)>Rv)continue;
    g.save();g.translate(c.x,c.y);g.rotate(c.a);const gr=g.createRadialGradient(20,0,4,90,0,120);gr.addColorStop(0,'rgba(0,0,0,0.85)');gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.beginPath();g.moveTo(16,0);g.lineTo(180,-55);g.lineTo(180,55);g.closePath();g.fill();
    const gr2=g.createRadialGradient(0,0,0,0,0,30);gr2.addColorStop(0,'rgba(0,0,0,0.6)');gr2.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr2;g.fillRect(-30,-30,60,60);g.restore();}
  ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(LIT,0,0);ctx.restore();
  if(sunset){ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalCompositeOperation='soft-light';ctx.fillStyle='rgba(255,130,40,.35)';ctx.fillRect(0,0,cv.width,cv.height);ctx.restore();}
  // pilotos traseros rojos que brillan de noche
  if(dark>0.35){ctx.save();ctx.translate(cx,cy);if(rot)ctx.rotate(cam.rot);ctx.scale(z,z);ctx.translate(-cam.x,-cam.y);ctx.globalCompositeOperation='lighter';
    for(const c of R.cars){if(c.dnf||c.gone||Math.abs(c.x-cam.x)>Rv||Math.abs(c.y-cam.y)>Rv)continue;const bx=c.x-Math.cos(c.a)*19,by=c.y-Math.sin(c.a)*19,rr=c.brake>0.2?9:5;
      const gr=ctx.createRadialGradient(bx,by,0,bx,by,rr);gr.addColorStop(0,'rgba(255,40,30,.9)');gr.addColorStop(1,'rgba(255,40,30,0)');ctx.fillStyle=gr;ctx.fillRect(bx-rr,by-rr,rr*2,rr*2);}
    ctx.restore();}
}

