  const S=3,o=document.createElement('canvas');o.width=52*S;o.height=32*S;const g=o.getContext('2d');
  g.scale(S,S);g.translate(26,16);g.lineJoin='round';g.lineCap='round';
  const col=c.color,c2=c.color2,tc=COMPOUNDS[c.compound].color;
  const rr=(x,y,w,h,r)=>{g.beginPath();if(g.roundRect)g.roundRect(x,y,w,h,r);else g.rect(x,y,w,h);};
  const tyre=(x,y,w,h)=>{const tg=g.createLinearGradient(0,y,0,y+h);tg.addColorStop(0,'#0c0c0c');tg.addColorStop(0.5,'#262626');tg.addColorStop(1,'#0c0c0c');
    g.fillStyle=tg;rr(x,y,w,h,1.8);g.fill();
    g.strokeStyle='rgba(255,255,255,.07)';g.lineWidth=0.35;for(let k=x+1.2;k<x+w-0.6;k+=1.6){g.beginPath();g.moveTo(k,y+0.7);g.lineTo(k,y+h-0.7);g.stroke();}
    g.fillStyle=tc;g.fillRect(x+w*0.5-0.45,y<0?y+0.25:y+h-1.05,0.9,0.8);};
