const PHOTOS={};
function loadPhoto(src){let im=PHOTOS[src];if(!im){im=new Image();im.onload=()=>clearTiles();im.onerror=()=>{im.failed=true;clearTiles();};im.src=src;PHOTOS[src]=im;}return im;}
