  if(!ph){ /* v45: goma de las frenadas (dos ruedas por pasada) y salchichas amarillas */ ctx.save();ctx.lineCap='round';ctx.strokeStyle='rgba(14,14,16,.16)';ctx.lineWidth=3.2;for(const c of vis)ctx.stroke(c.brk);ctx.strokeStyle='rgba(14,14,16,.10)';ctx.lineWidth=5;for(const c of vis)ctx.stroke(c.brk);
    ctx.lineCap='butt';ctx.setLineDash([7,4]);ctx.strokeStyle='rgba(0,0,0,.3)';ctx.lineWidth=7;for(const c of vis)ctx.stroke(c.saus);ctx.strokeStyle='#f2c200';ctx.lineWidth=5;for(const c of vis)ctx.stroke(c.saus);ctx.strokeStyle='rgba(255,255,255,.35)';ctx.lineWidth=1.2;for(const c of vis)ctx.stroke(c.saus);ctx.setLineDash([]);ctx.restore();}
  ctx.fillStyle='rgba(18,18,22,.11)';for(const c of vis)ctx.fill(c.patch);ctx.strokeStyle='rgba(0,0,0,.10)';ctx.lineWidth=1;for(const c of vis)ctx.stroke(c.patch);
  S('rgba(10,10,12,.13)',64,'path');
