  const fc=g.createRadialGradient(0,-r*0.25,r*0.05,0,0,r);fc.addColorStop(0,'#262b33');fc.addColorStop(1,'#0c0e12');g.fillStyle=fc;g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.fill();
