  // arcos: gasolina (izquierda, crece hacia arriba) y temperatura del motor (derecha)
  ctx.save();ctx.lineCap='round';ctx.lineWidth=r*0.075;
  const fu=clamp(p.fuel/TANK,0,1);ctx.strokeStyle='#42a5f5';ctx.shadowColor='#42a5f5';ctx.shadowBlur=r*0.15;
