  const part=(x,y,w,h,v)=>{ctx.fillStyle=stc(v);if(ctx.roundRect){ctx.beginPath();ctx.roundRect(x,y,w,h,Math.min(w,h)*0.3);ctx.fill();}else ctx.fillRect(x,y,w,h);};
  const engV=p.engineDead?1:p.issue?0.6:clamp(1-(p.eng==null?1:p.eng)*1.15,0,1)*0.9;
  part(L*0.41,-Wd*0.47,L*0.08,Wd*0.94,p.dWing||0);           // alerón delantero
  part(-L*0.5,-Wd*0.34,L*0.08,Wd*0.68,p.dRear||0);           // alerón trasero / difusor
  part(-L*0.06,-Wd*0.5,L*0.26,Wd*0.13,(p.suspSide||1)<0?p.dSusp||0:(p.dSusp||0)*0.3); // suspensión izquierda
  part(-L*0.06,Wd*0.37,L*0.26,Wd*0.13,(p.suspSide||1)>0?p.dSusp||0:(p.dSusp||0)*0.3); // suspensión derecha
  ctx.fillStyle=stc(engV);ctx.beginPath();ctx.arc(-L*0.2,0,Wd*0.17,0,Math.PI*2);ctx.fill();   // motor
