  const TS=p.tts||[TT,TT,TT,TT],WS=p.tws||[p.wear,p.wear,p.wear,p.wear];
  ctx.globalAlpha=0.9;const kk=L/DW;[[13.4,-5.5,4.9,2.1,0],[13.4,5.5,4.9,2.1,1],[-11,-5.4,4.9,2.75,2],[-11,5.4,4.9,2.75,3]].forEach(([x,y,w,h,i])=>{ctx.fillStyle=tc(TS[i]);ctx.fillRect((x-w/2)*kk,(y-h/2)*kk,w*kk,h*kk);});
  ctx.restore();ctx.globalAlpha=1;
  // temperatura y vida de cada neumático junto a su rueda (morro arriba: izquierda del coche = izquierda de la esfera)
  const F=k=>Math.round(Math.max(r*k,COMPACT?10*UI_U:0));const lf=F(0.135),gp=Math.max(r*0.075,lf*0.55);
  ctx.font=`800 ${lf}px ui-monospace,Menlo,monospace`;ctx.textBaseline='middle';
  [[0,-1,-0.36],[1,1,-0.36],[2,-1,0.16],[3,1,0.16]].forEach(([i,sx,dy])=>{const X=cx+sx*r*0.3,Y=cy+dy*r;ctx.textAlign=sx<0?'right':'left';
    ctx.fillStyle=tc(TS[i]);ctx.fillText(Math.round(TS[i])+'°',X,Y-gp);ctx.fillStyle='rgba(255,255,255,.85)';ctx.fillText(Math.round((1-WS[i])*100)+'%',X,Y+gp);});
  ctx.textAlign='center';
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillStyle=C.color;ctx.font=`800 ${F(0.15)}px system-ui,sans-serif`;ctx.fillText(C.name.toUpperCase()+' '+Math.round((1-p.wear)*100)+'%',cx,cy+r*0.5);
  const em=p.emode==null?1:p.emode,e=Math.round((p.eng==null?1:p.eng)*100);
  const fpl=fplOf(R,p);ctx.fillStyle='#8fd0ff';ctx.font=`700 ${F(0.11)}px ui-monospace,Menlo,monospace`;ctx.fillText(Math.round(p.fuel)+' L · '+(p.fuel/fpl).toFixed(1)+' v',cx,cy+r*0.68);
