  return; // en pantalla grande el estado va en la esfera junto al velocímetro (drawStatusDial)
  const p=R.player,small=VW<760,s=small?0.6:1,W0=176*s,H0=272*s;
  let x0=VW-W0-10,y0=small?(VH-H0-(document.body.classList.contains('touch')?250:150)):Math.max(70,VH/2-H0/2-30);
  ctx.save();ctx.translate(x0,y0);ctx.scale(s,s);
  ctx.fillStyle='rgba(9,22,52,.82)';ctx.beginPath();if(ctx.roundRect)ctx.roundRect(0,0,176,272,10);else ctx.rect(0,0,176,272);ctx.fill();
  ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 10px system-ui,sans-serif';ctx.fillStyle='#8f99a4';ctx.fillText('ESTADO DEL COCHE',88,12);
  // silueta: morro arriba
  const cx=58,top=28;
  const C=COMPOUNDS[p.compound],tw=p.punct?1:p.wear,TT=p.tt||80,tcol=p.punct?'#ff3b30':TT<C.win[0]-10?'#3d7bff':TT<C.win[0]?'#5ec8ff':TT<=C.win[1]?'#3ddc84':TT<=C.win[1]+10?'#ffb300':'#ff3b30';
  const tyre=(x,y,w,h,side)=>{ctx.fillStyle=(p.punct&&side===(p.suspSide||1))?'#ff3b30':tcol;ctx.globalAlpha=0.9;ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,3);else ctx.rect(x,y,w,h);ctx.fill();ctx.globalAlpha=1;
    ctx.strokeStyle=C.color;ctx.lineWidth=1.5;ctx.stroke();};
  // alerón delantero
