  ctx.strokeStyle=dmgCol(sL);ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(cx-8,top+28);ctx.lineTo(cx-26,top+28);ctx.moveTo(cx-10,top+128);ctx.lineTo(cx-28,top+128);ctx.stroke();
  ctx.strokeStyle=dmgCol(sR);ctx.beginPath();ctx.moveTo(cx+8,top+28);ctx.lineTo(cx+26,top+28);ctx.moveTo(cx+10,top+128);ctx.lineTo(cx+28,top+128);ctx.stroke();
  // ruedas
