  // carrocería
  ctx.fillStyle='#39414b';ctx.beginPath();ctx.moveTo(cx-4,top+7);ctx.lineTo(cx+4,top+7);ctx.lineTo(cx+7,top+50);ctx.lineTo(cx+20,top+66);ctx.lineTo(cx+20,top+108);ctx.lineTo(cx+10,top+146);ctx.lineTo(cx-10,top+146);ctx.lineTo(cx-20,top+108);ctx.lineTo(cx-20,top+66);ctx.lineTo(cx-7,top+50);ctx.closePath();ctx.fill();
