  ctx.fillStyle=dmgCol(eng);ctx.globalAlpha=0.85;ctx.beginPath();ctx.ellipse(cx,top+112,9,20,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
  // cabina
  ctx.fillStyle='#0d0f12';ctx.beginPath();ctx.ellipse(cx,top+74,6,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8fd0ff';ctx.beginPath();ctx.arc(cx,top+76,4,0,Math.PI*2);ctx.fill();
